//! Regenerates `src/gtt/proto.rs` from `gtfs-realtime.proto` (the official file from
//! https://github.com/google/transit, Apache 2.0). Run from anywhere:
//!
//! ```bash
//! cargo run --manifest-path tools/gtfs-rt-codegen/Cargo.toml
//! ```
//!
//! `protox` compiles the `.proto` in pure Rust, so no `protoc` is needed even here.

use std::{fs, path::Path};

const HEADER: &str = "\
// @generated by tools/gtfs-rt-codegen from gtfs-realtime.proto. Do not edit by hand:
// change the tool or the .proto and run it again.

";

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let descriptors = protox::compile(["gtfs-realtime.proto"], [dir])?;

    let out = dir.join("target/generated");
    fs::create_dir_all(&out)?;
    prost_build::Config::new()
        .out_dir(&out)
        .compile_fds(descriptors)?;

    let code = fs::read_to_string(out.join("transit_realtime.rs"))?;
    let target = dir.join("../../src/gtt/proto.rs");
    fs::write(&target, format!("{HEADER}{code}"))?;
    println!("wrote {}", target.display());
    Ok(())
}
